def compute(vars):
    ages = [vars["v1"], vars["v2"], vars["v3"]]
    total_age = sum(ages)
    count = len(ages)
    average_age = total_age / count
    return {
        "value": average_age,
        "trace": {
            "ages": ages,
            "total_age": total_age,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
